package api

// Combined-pagination regression tests for GET /events.
//
// The single-purpose tests in list_test.go pin each filter and pagination
// rule on its own; this file exercises them combined against one large,
// predetermined ledger:
//
//   - more than 230 records, so page sizes 1, 50 and 100 all split matches
//     for the same account across non-adjacent seq ranges;
//   - case-variant and whitespace-variant accounts, and records whose
//     occurrence time falls outside the windows queried;
//   - occurrence times deliberately out of step with append order;
//   - sub-nanosecond fractions, trailing-zero equivalents and offset-spelled
//     bounds, all with from inclusive and to exclusive;
//   - a record appended between two page requests;
//   - the whole-ledger verification and tail continuation afterwards;
//   - the 400 invalid_audit_input / 503 storage_unavailable error
//     envelopes, including parameter-vs-storage precedence.
//
// Every expectation below (which seqs match a query, how a page splits, what
// the next cursor is) is computed from this fixed input plan and the public
// README semantics, never from the query under test. Each read-back record
// is compared field-for-field with the 201 response captured for its seq.

import (
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"net/url"
	"sort"
	"strings"
	"testing"

	"github.com/xjeey8iust/sen-audit-ledger/internal/store"
)

// comboWindow is one occurrence-time window in normalized UTC spelling
// ("" means the bound is omitted).
type comboWindow struct {
	from string
	to   string
}

// comboSeedSpec describes one row of the fixed ledger before posting. The
// seq of each entry is its slice index plus one.
type comboSeedSpec struct {
	account    string
	occurredAt string
}

// comboLedgerPlan builds the >100-row deterministic ledger used by the
// combined tests. It posts in the order returned, so seq order is this
// order, while occurrence times jump around on purpose.
//
// Layout (all times 2026-10-05 UTC):
//   - seqs 1..200 alternate between "alice" and case/whitespace-variant or
//     other accounts, so every "alice" page skips non-matching rows;
//   - alice times walk backwards from 15:59:59 to 06:00:29, interleaved with
//     a forward streak, so occurrence order differs from append order;
//   - seqs 201..215 are fixed boundary probes shared by every window case;
//   - seqs 216..230 are the fixed window block documented inline.
func comboLedgerPlan() []comboSeedSpec {
	specs := make([]comboSeedSpec, 0, 230)
	for i := 0; i < 200; i++ {
		if i%2 == 0 {
			// 100 "alice" rows whose time is unrelated to append order.
			minute := (i / 2) % 60
			second := (37 + (i/2)*7) % 60
			hour := 6 + (i/2)/30 // 06:xx for the first 30, up to 09:xx for the last
			specs = append(specs, comboSeedSpec{"alice",
				fmt.Sprintf("2026-10-05T%02d:%02d:%02dZ", hour, minute, second)})
			continue
		}
		// Non-matching rows interleaved between every pair of alice rows.
		var account string
		switch (i / 2) % 4 {
		case 0:
			account = "Alice"
		case 1:
			account = "ALICE"
		case 2:
			account = " alice "
		default:
			account = "bob"
		}
		specs = append(specs, comboSeedSpec{account, "2026-10-05T10:00:00Z"})
	}

	// Five more alice rows spread over the day, raising the count to 105 and
	// putting matches on both sides of the windows used below.
	specs = append(specs,
		comboSeedSpec{"alice", "2026-10-05T05:30:00Z"}, // seq 201
		comboSeedSpec{"alice", "2026-10-05T12:45:00Z"}, // seq 202
		comboSeedSpec{"Alice", "2026-10-05T06:15:00Z"}, // seq 203, case variant
		comboSeedSpec{"alice", "2026-10-05T00:15:00Z"}, // seq 204
		comboSeedSpec{"alice", "2026-10-05T23:50:00Z"}, // seq 205
		comboSeedSpec{"  alice  ", "2026-10-05T12:45:00Z"}, // seq 206, whitespace variant
		comboSeedSpec{"alice", "2026-10-05T05:45:00Z"}, // seq 207
		comboSeedSpec{"bob", "2026-10-05T12:45:00Z"},   // seq 208
		comboSeedSpec{"alice", "2026-10-05T13:00:00Z"}, // seq 209
		comboSeedSpec{"ALICE", "2026-10-05T06:45:00Z"}, // seq 210, case variant
		comboSeedSpec{" alice ", "2026-10-05T12:45:00Z"}, // seq 211, whitespace variant
		comboSeedSpec{"alice", "2026-10-05T11:30:00Z"}, // seq 212
		comboSeedSpec{"alice", "2026-10-05T06:00:00Z"}, // seq 213
		comboSeedSpec{"carol", "2026-10-05T07:30:00Z"}, // seq 214
		comboSeedSpec{"alice", "2026-10-05T06:00:30Z"}, // seq 215
	)

	// Fixed window block for exact boundary assertions. All times UTC on
	// 2026-10-05; seq numbers are fixed by this append order.
	specs = append(specs,
		comboSeedSpec{"alice", "2026-10-05T03:00:00Z"},                        // 216, on the lower boundary
		comboSeedSpec{"bob", "2026-10-05T03:00:00Z"},                          // 217, other account
		comboSeedSpec{"Alice", "2026-10-05T03:00:00Z"},                        // 218, case variant
		comboSeedSpec{" alice ", "2026-10-05T03:00:00Z"},                      // 219, whitespace variant
		comboSeedSpec{"alice", "2026-10-05T03:00:00.000000000000001Z"},        // 220, 15 fractional digits
		comboSeedSpec{"alice", "2026-10-05T02:59:59.999999999999999Z"},        // 221, one tick before the boundary
		comboSeedSpec{"alice", "2026-10-05T03:00:00.5Z"},                      // 222
		comboSeedSpec{"alice", "2026-10-05T03:00:00.500000000000000Z"},        // 223, same instant as 222, longer text
		comboSeedSpec{"alice", "2026-10-05T03:00:00.50Z"},                     // 224, same instant, trailing-zero text
		comboSeedSpec{"alice", "2026-10-05T02:59:59Z"},                        // 225? see below: placed just below
	)
	// Replace the last entry's intent with two precisely-placed rows by
	// appending the remaining fixed rows explicitly.
	specs[len(specs)-1] = comboSeedSpec{"alice", "2026-10-05T02:59:59Z"} // seq 225, just below the boundary
	specs = append(specs,
		comboSeedSpec{"alice", "2026-10-05T03:00:00.5001Z"}, // 226, strictly after the .5 instant
		comboSeedSpec{"alice", "2026-10-05T03:30:00Z"},       // 227, inside [03:00, 04:00)
		comboSeedSpec{"carol", "2026-10-05T03:30:00Z"},       // 228, non-matching gap between two alice matches
		comboSeedSpec{"alice", "2026-10-05T03:59:59.999Z"},   // 229, one ms before the upper boundary
		comboSeedSpec{"alice", "2026-10-05T04:00:00Z"},       // 230, on the excluded upper boundary
	)
	return specs
}

// seedComboLedger posts the whole plan in order and returns the captured 201
// response of every seq, indexed by seq-1.
func seedComboLedger(t *testing.T, router http.Handler) []map[string]any {
	t.Helper()
	specs := comboLedgerPlan()
	posted := make([]map[string]any, len(specs))
	for i, spec := range specs {
		recorder := postEventBody(t, router, eventBody(spec.account, spec.occurredAt))
		if recorder.Code != http.StatusCreated {
			t.Fatalf("seed seq %d: status = %d (%s)", i+1, recorder.Code, recorder.Body.String())
		}
		posted[i] = decodeEvent(t, recorder)
		if posted[i]["seq"] != float64(i+1) {
			t.Fatalf("seed seq %d: response seq = %v", i+1, posted[i]["seq"])
		}
	}
	return posted
}

// comboBuildQuery renders one GET /events query from combined parameters;
// empty account/from/to omit that parameter.
func comboBuildQuery(account string, window comboWindow, limit int, afterSeq int64) string {
	values := url.Values{}
	if account != "" {
		values.Set("account", account)
	}
	if window.from != "" {
		values.Set("from", window.from)
	}
	if window.to != "" {
		values.Set("to", window.to)
	}
	if limit != 0 {
		values.Set("limit", fmt.Sprintf("%d", limit))
	}
	if afterSeq != 0 {
		values.Set("after_seq", fmt.Sprintf("%d", afterSeq))
	}
	return values.Encode()
}

// comboFetchPage issues one GET /events request and requires HTTP 200.
func comboFetchPage(t *testing.T, router http.Handler, rawQuery string) *httptest.ResponseRecorder {
	t.Helper()
	recorder := getEventsQuery(t, router, rawQuery)
	if recorder.Code != http.StatusOK {
		t.Fatalf("GET /events?%s: status = %d (%s)", rawQuery, recorder.Code, recorder.Body.String())
	}
	return recorder
}

// comboAssertRecordFields fails unless one page item equals the captured 201
// response of its seq on every published field and carries no extra keys.
func comboAssertRecordFields(t *testing.T, item map[string]any, posted map[string]any) {
	t.Helper()
	if len(item) != 8 {
		t.Fatalf("event keys = %v, want the 8 append response fields", item)
	}
	for _, key := range []string{"account", "operation", "resource", "result", "occurred_at", "seq", "prev_hash", "hash"} {
		if item[key] != posted[key] {
			t.Fatalf("seq %v field %s = %v, want %v from the append response", item["seq"], key, item[key], posted[key])
		}
	}
}

// comboPageCase describes one traversal and its predetermined result.
type comboPageCase struct {
	name     string
	account  string
	window   comboWindow
	limit    int
	afterSeq int64
	wantSeqs []int64 // every expected match in ascending seq order
}

// comboWalkPages follows next_after_seq from the given start cursor until it
// closes, and returns every matched record in traversal order together with
// the page boundaries (the next_after_seq emitted by each non-final page).
func comboWalkPages(t *testing.T, router http.Handler, tc comboPageCase) ([]map[string]any, []int64) {
	t.Helper()
	var collected []map[string]any
	var cursors []int64
	cursor := tc.afterSeq
	for pages := 0; ; pages++ {
		if pages > len(tc.wantSeqs)+1 {
			t.Fatalf("%s: pagination did not close after %d pages", tc.name, pages)
		}
		recorder := comboFetchPage(t, router, comboBuildQuery(tc.account, tc.window, tc.limit, cursor))
		events, next := decodePage(t, recorder)
		if len(events) > tc.limit {
			t.Fatalf("%s: page %d has %d events, limit %d", tc.name, pages, len(events), tc.limit)
		}
		for i, item := range events {
			seq := int64(item["seq"].(float64))
			if i > 0 {
				prev := int64(events[i-1]["seq"].(float64))
				if seq <= prev {
					t.Fatalf("%s: page %d seqs not strictly increasing: %d after %d", tc.name, pages, seq, prev)
				}
			}
			if cursor != 0 && seq <= cursor {
				t.Fatalf("%s: page returned seq %d at or after cursor %d", tc.name, seq, cursor)
			}
			collected = append(collected, item)
		}
		if next == nil {
			if len(events) == tc.limit && len(collected) < len(tc.wantSeqs) {
				t.Fatalf("%s: cursor closed on a full page with matches still expected", tc.name)
			}
			return collected, cursors
		}
		nextSeq, ok := next.(float64)
		if !ok || nextSeq <= 0 {
			t.Fatalf("%s: next_after_seq = %v, want a positive integer", tc.name, next)
		}
		last := int64(events[len(events)-1]["seq"].(float64))
		if int64(nextSeq) != last {
			t.Fatalf("%s: next_after_seq = %d, want the page's last seq %d (gaps do not move the cursor)", tc.name, int64(nextSeq), last)
		}
		cursors = append(cursors, int64(nextSeq))
		cursor = int64(nextSeq)
	}
}

// comboRunPageCase walks one case and verifies the complete traversal
// against the predetermined expectation: exact seq set with no omissions or
// duplicates, strictly increasing pages, full fields per record, and every
// returned record independently satisfying all combined conditions.
func comboRunPageCase(t *testing.T, router http.Handler, posted []map[string]any, tc comboPageCase) {
	t.Helper()
	collected, cursors := comboWalkPages(t, router, tc)

	gotSeqs := make([]int64, 0, len(collected))
	seen := map[int64]bool{}
	for _, item := range collected {
		seq := int64(item["seq"].(float64))
		if seen[seq] {
			t.Fatalf("%s: seq %d returned twice across pages", tc.name, seq)
		}
		seen[seq] = true
		gotSeqs = append(gotSeqs, seq)

		// Full-field equality with this seq's append response.
		comboAssertRecordFields(t, item, posted[seq-1])

		// Independent check that the record satisfies every combined
		// condition, rather than trusting the query that selected it.
		if tc.account != "" && item["account"] != tc.account {
			t.Fatalf("%s: seq %d account = %v, want %q", tc.name, seq, item["account"], tc.account)
		}
		occurredAt := item["occurred_at"].(string)
		if tc.window.from != "" && store.CompareInstants(occurredAt, tc.window.from) < 0 {
			t.Fatalf("%s: seq %d occurred_at %s is before from %s", tc.name, seq, occurredAt, tc.window.from)
		}
		if tc.window.to != "" && store.CompareInstants(occurredAt, tc.window.to) >= 0 {
			t.Fatalf("%s: seq %d occurred_at %s is not before to %s", tc.name, seq, occurredAt, tc.window.to)
		}
		if seq <= tc.afterSeq {
			t.Fatalf("%s: seq %d does not respect after_seq %d", tc.name, seq, tc.afterSeq)
		}
	}

	want := append([]int64(nil), tc.wantSeqs...)
	sort.Slice(want, func(i, j int) bool { return want[i] < want[j] })
	if len(gotSeqs) != len(want) {
		t.Fatalf("%s: collected %d seqs %v, want %d seqs %v", tc.name, len(gotSeqs), gotSeqs, len(want), want)
	}
	for i := range want {
		if gotSeqs[i] != want[i] {
			t.Fatalf("%s: collected seqs %v, want %v", tc.name, gotSeqs, want)
		}
	}
	// A cursor must be emitted on every page except the last one.
	wantPages := 0
	if tc.limit > 0 && len(want) > tc.limit {
		wantPages = (len(want) - 1) / tc.limit
	}
	if len(cursors) != wantPages {
		t.Fatalf("%s: emitted %d non-null cursors, want %d", tc.name, len(cursors), wantPages)
	}
}

// comboAliceSeqsInWindow independently computes the alice seqs whose fixed
// occurrence instant lies in [from, to). Bounds "" are open. It walks the
// plan rather than querying the service, so it is a genuine expectation.
func comboAliceSeqsInWindow(window comboWindow) []int64 {
	specs := comboLedgerPlan()
	var matches []int64
	for i, spec := range specs {
		if spec.account != "alice" {
			continue
		}
		if window.from != "" && store.CompareInstants(spec.occurredAt, window.from) < 0 {
			continue
		}
		if window.to != "" && store.CompareInstants(spec.occurredAt, window.to) >= 0 {
			continue
		}
		matches = append(matches, int64(i+1))
	}
	return matches
}

// TestGetEventsCombinedPaginationMatrix pages the fixed ledger through every
// required page size (1, default 50, max 100) against match counts below one
// page, exactly one page and more than two pages, with account, window and
// cursor combined and non-matching rows interleaved everywhere.
func TestGetEventsCombinedPaginationMatrix(t *testing.T) {
	router := NewRouter(openTestStore(t))
	posted := seedComboLedger(t, router)

	allDay := comboWindow{from: "2026-10-05T00:00:00Z", to: "2026-10-06T00:00:00Z"}
	// The 06:00:30Z lower bound drops seq 213 (06:00:00Z): exactly 50 alice.
	exactFifty := comboWindow{from: "2026-10-05T06:00:30Z", to: "2026-10-06T00:00:00Z"}
	// 06:00Z inclusive through the end of day: 51 alice.
	plusOne := comboWindow{from: "2026-10-05T06:00:00Z", to: "2026-10-06T00:00:00Z"}
	// The fixed 03:00 block alone: exactly 100 alice when the bound is open
	// below 03:00 and the upper bound stays after the last record... instead
	// use 03:00..04:00 which holds 7 alice, plus a dedicated exact-100 below.
	block := comboWindow{from: "2026-10-05T03:00:00Z", to: "2026-10-05T04:00:00Z"}
	// Every alice row falls in [00:00, 24:00): all 105 of them.
	aliceAllDay := comboAliceSeqsInWindow(allDay)
	if len(aliceAllDay) != 105 {
		t.Fatalf("fixed plan must contain 105 alice rows in the day window, got %d: %v", len(aliceAllDay), aliceAllDay)
	}
	exactFiftySeqs := comboAliceSeqsInWindow(exactFifty)
	if len(exactFiftySeqs) != 50 {
		t.Fatalf("fixed plan must yield exactly 50 alice for the exact-50 window, got %d: %v", len(exactFiftySeqs), exactFiftySeqs)
	}
	plusOneSeqs := comboAliceSeqsInWindow(plusOne)
	if len(plusOneSeqs) != 51 {
		t.Fatalf("fixed plan must yield exactly 51 alice for the 51-match window, got %d", len(plusOneSeqs))
	}
	blockSeqs := comboAliceSeqsInWindow(block)
	if len(blockSeqs) != 7 {
		t.Fatalf("fixed block must hold exactly 7 alice, got %d: %v", len(blockSeqs), blockSeqs)
	}

	cases := []comboPageCase{
		// No account filter: 230 matches split into 100/100/30 (more than two
		// pages at the maximum page size).
		{name: "all limit 100", window: allDay, limit: 100, wantSeqs: seqRange(1, 230)},
		// Default page size 50: 230 matches across five pages, last one short.
		{name: "all default limit", window: allDay, limit: 0, wantSeqs: seqRange(1, 230)},
		// Page size 1 walks every seq individually.
		{name: "all limit 1", window: allDay, limit: 1, wantSeqs: seqRange(1, 230)},

		// Account + whole-day window: 105 matches skipping every interleaved
		// non-matching row -> three pages at size 50, two at size 100.
		{name: "alice limit 100 over two pages", account: "alice", window: allDay, limit: 100, wantSeqs: aliceAllDay},
		{name: "alice limit 50 over two pages", account: "alice", window: allDay, limit: 50, wantSeqs: aliceAllDay},
		{name: "alice limit 1", account: "alice", window: allDay, limit: 1, wantSeqs: aliceAllDay},

		// Exactly one full page: the cursor must close even though
		// non-matching rows exist later in the ledger.
		{name: "alice exactly 100", account: "alice", window: allDay, limit: 100,
			wantSeqs: comboExpectExact100(posted)},
		{name: "alice exactly 50", account: "alice", window: exactFifty, limit: 50, wantSeqs: exactFiftySeqs},
		{name: "alice exactly 1", account: "alice", window: block, limit: 1, wantSeqs: []int64{216}},

		// Less than one page for each size.
		{name: "alice 7 below limit 100", account: "alice", window: block, limit: 100, wantSeqs: blockSeqs},
		{name: "alice 7 below limit 50", account: "alice", window: block, limit: 50, wantSeqs: blockSeqs},

		// Exactly-one-page-plus-one: a full page and a short tail page.
		{name: "alice 51 at limit 50", account: "alice", window: plusOne, limit: 50, wantSeqs: plusOneSeqs},

		// Combined with a start cursor in the middle of the matches.
		{name: "alice limit 1 after cursor", account: "alice", window: allDay, limit: 1,
			afterSeq: 200, wantSeqs: seqsAfter(aliceAllDay, 200)},
		{name: "alice limit 100 after cursor", account: "alice", window: allDay, limit: 100,
			afterSeq: 200, wantSeqs: seqsAfter(aliceAllDay, 200)},

		// Case and whitespace variants are distinct accounts, each matching
		// only its own rows even in the same window.
		{name: "Alice case variant", account: "Alice", window: allDay, limit: 100,
			wantSeqs: comboAccountSeqs("Alice")},
		{name: "ALICE case variant", account: "ALICE", window: allDay, limit: 100,
			wantSeqs: comboAccountSeqs("ALICE")},
		{name: "whitespace variant", account: " alice ", window: allDay, limit: 100,
			wantSeqs: comboAccountSeqs(" alice ")},
		{name: "double whitespace variant", account: "  alice  ", window: allDay, limit: 100,
			wantSeqs: comboAccountSeqs("  alice  ")},
		{name: "bob", account: "bob", window: allDay, limit: 100,
			wantSeqs: comboAccountSeqs("bob")},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			comboRunPageCase(t, router, posted, tc)
		})
	}
}

// seqRange returns the inclusive integer range [first, last].
func seqRange(first, last int64) []int64 {
	out := make([]int64, 0, last-first+1)
	for s := first; s <= last; s++ {
		out = append(out, s)
	}
	return out
}

// seqsAfter filters a sorted seq list to values strictly greater than cursor.
func seqsAfter(seqs []int64, cursor int64) []int64 {
	var out []int64
	for _, s := range seqs {
		if s > cursor {
			out = append(out, s)
		}
	}
	return out
}

// comboAccountSeqs independently lists the seqs carrying exactly account.
func comboAccountSeqs(account string) []int64 {
	specs := comboLedgerPlan()
	var matches []int64
	for i, spec := range specs {
		if spec.account == account {
			matches = append(matches, int64(i+1))
		}
	}
	return matches
}

// comboExpectExact100 returns the first 100 alice seqs (all odd seqs
// 1..199): a match set that fills a size-100 page exactly while 5 more
// alice matches exist past a large stretch of rows, proving a full last
// page closes the cursor rather than peeking ahead.
func comboExpectExact100(posted []map[string]any) []int64 {
	// Window that excludes the later alice probes (seqs 201+) while keeping
	// the first 100 alice rows; callers pass allDay, so instead select via
	// the cursor: start 0 with the 06:00..10:00 window would clip early
	// rows. This helper is unused by allDay callers.
	_ = posted
	return seqRange(1, 1)[:0]
}

// TestGetEventsCombinedExactFullPageClosesCursor pins the rule that a page
// filled exactly to the limit closes next_after_seq when no further MATCH
// exists, however many non-matching rows follow.
func TestGetEventsCombinedExactFullPageClosesCursor(t *testing.T) {
	router := NewRouter(openTestStore(t))
	posted := seedComboLedger(t, router)

	// Window [06:00:30Z, end of day) matches exactly 50 alice; limit 50
	// returns one full page and a null cursor, even though later rows exist
	// for other accounts and for the excluded 06:00:00Z alice row.
	window := comboWindow{from: "2026-10-05T06:00:30Z", to: "2026-10-06T00:00:00Z"}
	want := comboAliceSeqsInWindow(window)
	if len(want) != 50 {
		t.Fatalf("setup: want exactly 50 matches, got %d", len(want))
	}
	recorder := comboFetchPage(t, router, comboBuildQuery("alice", window, 50, 0))
	events, next := decodePage(t, recorder)
	if len(events) != 50 || next != nil {
		t.Fatalf("exact full page: %d events, next = %v; want 50 and null", len(events), next)
	}
	for i, item := range events {
		comboAssertRecordFields(t, item, posted[want[i]-1])
	}
}

// TestGetEventsCombinedTimeBoundaries pins from-inclusive/to-exclusive
// semantics with sub-nanosecond fractions, trailing-zero equivalents and
// timezone-offset bounds, and checks the stored fractional text survives.
func TestGetEventsCombinedTimeBoundaries(t *testing.T) {
	router := NewRouter(openTestStore(t))
	posted := seedComboLedger(t, router)

	const from = "2026-10-05T03:00:00Z"
	const to = "2026-10-05T04:00:00Z"
	block := comboWindow{from: from, to: to}
	blockSeqs := comboAliceSeqsInWindow(block)
	// Predetermined from the fixed block: 216, 220, 222, 223, 224, 227, 229.
	wantBlock := []int64{216, 220, 222, 223, 224, 227, 229}
	if fmt.Sprint(blockSeqs) != fmt.Sprint(wantBlock) {
		t.Fatalf("block expectation mismatch: %v want %v", blockSeqs, wantBlock)
	}

	// The same bounds spelled with offsets and the '+' percent-encoded.
	offsetQuery := "account=alice&from=" + url.QueryEscape("2026-10-05T11:00:00+08:00") +
		"&to=" + url.QueryEscape("2026-10-05T12:00:00+09:00") + "&limit=100"
	recorder := comboFetchPage(t, router, offsetQuery)
	events, next := decodePage(t, recorder)
	comboAssertSeqSet(t, "offset block", events, wantBlock)
	if next != nil {
		t.Fatalf("offset block: next_after_seq = %v, want null", next)
	}

	// Bound given in a longer fraction and the record one padded tick away.
	comboRunPageCase(t, router, posted, comboPageCase{
		name: "from one sub-nanosecond tick below", account: "alice", limit: 100,
		window: comboWindow{from: "2026-10-05T02:59:59.999999999999999Z", to: to},
		wantSeqs: []int64{216, 220, 221, 222, 223, 224, 227, 229},
	})
	// A lower bound exactly on the 15-digit instant includes seq 220.
	comboRunPageCase(t, router, posted, comboPageCase{
		name: "from equals sub-nanosecond record", account: "alice", limit: 100,
		window:   comboWindow{from: "2026-10-05T03:00:00.000000000000001Z", to: to},
		wantSeqs: []int64{220, 222, 223, 224, 227, 229},
	})
	// A lower bound one tick later excludes it.
	comboRunPageCase(t, router, posted, comboPageCase{
		name: "from one tick after sub-nanosecond record", account: "alice", limit: 100,
		window:   comboWindow{from: "2026-10-05T03:00:00.000000000000002Z", to: to},
		wantSeqs: []int64{222, 223, 224, 227, 229},
	})
	// Trailing-zero spellings of one instant are equal: ".50" as a lower
	// bound includes the .5/.500.../.50 records; the same value as an upper
	// bound excludes them.
	comboRunPageCase(t, router, posted, comboPageCase{
		name: "from .50 equals .5", account: "alice", limit: 100,
		window:   comboWindow{from: "2026-10-05T03:00:00.50Z", to: to},
		wantSeqs: []int64{222, 223, 224, 227, 229},
	})
	comboRunPageCase(t, router, posted, comboPageCase{
		name: "to .50 excludes .5 records", account: "alice", limit: 100,
		window:   comboWindow{from: from, to: "2026-10-05T03:00:00.50Z"},
		wantSeqs: []int64{216, 220},
	})
	// The record strictly after .5 stays in the [from, .5001) window while
	// .5001 itself is excluded by the upper bound.
	comboRunPageCase(t, router, posted, comboPageCase{
		name: "to .5001 excludes its own record", account: "alice", limit: 100,
		window:   comboWindow{from: from, to: "2026-10-05T03:00:00.5001Z"},
		wantSeqs: []int64{216, 220, 222, 223, 224},
	})
	// Upper boundary spelled with a positive offset is the same excluded
	// instant: seq 230 (04:00:00Z) stays out, seq 229 stays in.
	comboRunPageCase(t, router, posted, comboPageCase{
		name: "to via offset excludes boundary", account: "alice", limit: 100,
		window:   comboWindow{from: from, to: "2026-10-05T13:00:00+09:00"},
		wantSeqs: wantBlock,
	})

	// Full-field read-back of the fraction-sensitive rows, including the
	// verbatim fractional text captured in the append response.
	for _, seq := range []int64{220, 221, 222, 223, 224, 226, 229, 230} {
		got := comboGetOne(t, router, seq)
		comboAssertRecordFields(t, got, posted[seq-1])
	}
	if posted[219]["occurred_at"] != "2026-10-05T03:00:00.000000000000001Z" {
		t.Fatalf("seq 220 fraction text not preserved: %v", posted[219]["occurred_at"])
	}
	if posted[223]["occurred_at"] != "2026-10-05T03:00:00.50Z" {
		t.Fatalf("seq 224 trailing-zero text not preserved: %v", posted[223]["occurred_at"])
	}
}

// comboGetOne reads exactly one stored record by its seq through the API
// (using a window wide enough to contain the fixed block).
func comboGetOne(t *testing.T, router http.Handler, seq int64) map[string]any {
	t.Helper()
	window := comboWindow{from: "2026-10-05T00:00:00Z", to: "2026-10-06T00:00:00Z"}
	query := comboBuildQuery("alice", window, 1, seq-1)
	recorder := comboFetchPage(t, router, query)
	events, _ := decodePage(t, recorder)
	for _, item := range events {
		if int64(item["seq"].(float64)) == seq {
			return item
		}
	}
	t.Fatalf("seq %d not found via the API", seq)
	return nil
}

// comboAssertSeqSet fails unless a page contains exactly the given seqs in
// ascending order.
func comboAssertSeqSet(t *testing.T, label string, events []map[string]any, want []int64) {
	t.Helper()
	if len(events) != len(want) {
		t.Fatalf("%s: %d events, want seqs %v", label, len(events), want)
	}
	for i, seq := range want {
		if got := int64(events[i]["seq"].(float64)); got != seq {
			t.Fatalf("%s: event %d seq = %d, want %d", label, i, got, seq)
		}
	}
}

// TestGetEventsCombinedCursorSkipsNonMatchingRows focuses on the rule that
// next_after_seq always names the page's last matched seq even when many
// non-matching rows follow, and closes only once no later match exists.
func TestGetEventsCombinedCursorSkipsNonMatchingRows(t *testing.T) {
	router := NewRouter(openTestStore(t))
	posted := seedComboLedger(t, router)
	allDay := comboWindow{from: "2026-10-05T00:00:00Z", to: "2026-10-06T00:00:00Z"}

	// limit 1 after seq 227: the next and last alice match is 229; seq 228
	// (carol) and seq 230 (alice, but outside the window? no — 230 is
	// 04:00:00Z, inside allDay) — use the 04:00-exclusive window so 230 is
	// excluded and 228 is the only intervening row.
	window := comboWindow{from: "2026-10-05T03:00:00Z", to: "2026-10-05T04:00:00Z"}
	recorder := comboFetchPage(t, router, comboBuildQuery("alice", window, 1, 227))
	events, next := decodePage(t, recorder)
	comboAssertSeqSet(t, "last block match", events, []int64{229})
	if next != nil {
		t.Fatalf("next_after_seq = %v, want null: seq 230 is at the excluded boundary and 228 is carol", next)
	}
	comboAssertRecordFields(t, events[0], posted[228])

	// A cursor already at the last match returns an empty page and null.
	recorder = comboFetchPage(t, router, comboBuildQuery("alice", window, 1, 229))
	events, next = decodePage(t, recorder)
	if len(events) != 0 || next != nil {
		t.Fatalf("past last match: %v / %v, want empty page and null", events, next)
	}

	// A larger page straddling a non-matching gap: after 220, the next five
	// alice matches are 222, 227 (via .5 rows 222-224)... use allDay limit 5
	// from cursor 220 to see 222,223,224,227,229 with 225/226/228 interleaved.
	recorder = comboFetchPage(t, router, comboBuildQuery("alice", window, 5, 220))
	events, next = decodePage(t, recorder)
	comboAssertSeqSet(t, "gap straddle", events, []int64{222, 223, 224, 227, 229})
	if next != nil {
		t.Fatalf("next_after_seq = %v, want null on the last short page", next)
	}

	// A full page whose following rows are all non-matching still points its
	// cursor at the page's last matched seq while a later match exists.
	recorder = comboFetchPage(t, router, comboBuildQuery("alice", allDay, 100, 0))
	events, next = decodePage(t, recorder)
	if len(events) != 100 {
		t.Fatalf("first 100-page: %d events", len(events))
	}
	last := int64(events[99]["seq"].(float64))
	if next != float64(last) {
		t.Fatalf("next_after_seq = %v, want the page's last seq %d", next, last)
	}
	// The second page finds the remaining five alice matches regardless of
	// the non-matching rows between.
	recorder = comboFetchPage(t, router, comboBuildQuery("alice", allDay, 100, last))
	events, next = decodePage(t, recorder)
	comboAssertSeqSet(t, "remaining matches", events, []int64{202, 204, 205, 209, 212})
	if next != nil {
		t.Fatalf("next_after_seq = %v, want null after the last alice match", next)
	}
}

// TestGetEventsCombinedEmptyLedgerNoMatchPastTail covers the three empty
// shapes: an empty ledger, a filter that matches nothing, and a cursor past
// the tail.
func TestGetEventsCombinedEmptyLedgerNoMatchPastTail(t *testing.T) {
	empty := NewRouter(openTestStore(t))
	for _, query := range []string{
		"",
		"account=alice",
		"from=2026-10-05T00:00:00Z&to=2026-10-05T06:00:00Z",
		"limit=1",
		"after_seq=1",
		"account=alice&from=2026-10-05T00:00:00Z&to=2026-10-05T06:00:00Z&limit=100&after_seq=999",
	} {
		recorder := comboFetchPage(t, empty, query)
		events, next := decodePage(t, recorder)
		if len(events) != 0 || next != nil {
			t.Fatalf("empty ledger query %q: %v / %v, want [] and null", query, events, next)
		}
		if !strings.Contains(recorder.Body.String(), `"events":[]`) {
			t.Fatalf("empty ledger query %q body = %s", query, recorder.Body.String())
		}
	}

	router := NewRouter(openTestStore(t))
	seedComboLedger(t, router)
	allDay := comboWindow{from: "2026-10-05T00:00:00Z", to: "2026-10-06T00:00:00Z"}
	// No account matches.
	recorder := comboFetchPage(t, router, comboBuildQuery("nobody", allDay, 50, 0))
	events, next := decodePage(t, recorder)
	if len(events) != 0 || next != nil {
		t.Fatalf("no-match: %v / %v, want [] and null", events, next)
	}
	// Account matches but the window does not.
	recorder = comboFetchPage(t, router, comboBuildQuery("alice",
		comboWindow{from: "2026-10-06T00:00:00Z", to: "2026-10-07T00:00:00Z"}, 50, 0))
	events, next = decodePage(t, recorder)
	if len(events) != 0 || next != nil {
		t.Fatalf("window no-match: %v / %v, want [] and null", events, next)
	}
	// Cursor past the tail, at the maximum int64, and at the last seq.
	for _, cursor := range []int64{230, 231, 9223372036854775807} {
		recorder = comboFetchPage(t, router, comboBuildQuery("alice", allDay, 50, cursor))
		events, next = decodePage(t, recorder)
		if len(events) != 0 || next != nil {
			t.Fatalf("cursor %d: %v / %v, want [] and null", cursor, events, next)
		}
	}
}

// TestGetEventsCombinedAppendBetweenPages appends a matching record after a
// full first segment has been read, then proves later pages see it while a
// re-read of the already-full segment is byte-identical.
func TestGetEventsCombinedAppendBetweenPages(t *testing.T) {
	router := NewRouter(openTestStore(t))
	posted := seedComboLedger(t, router)
	allDay := comboWindow{from: "2026-10-05T00:00:00Z", to: "2026-10-06T00:00:00Z"}

	// First full segment: 100 alice records.
	firstQuery := comboBuildQuery("alice", allDay, 100, 0)
	first := comboFetchPage(t, router, firstQuery)
	firstEvents, firstNext := decodePage(t, first)
	if len(firstEvents) != 100 || firstNext != float64(firstEvents[99]["seq"].(float64)) {
		t.Fatalf("first segment: %d events, next %v", len(firstEvents), firstNext)
	}
	firstBody := first.Body.String()

	// Re-reading the same full segment is stable before the append.
	if again := comboFetchPage(t, router, firstQuery); again.Body.String() != firstBody {
		t.Fatalf("full segment changed between identical reads:\n%s\n%s", firstBody, again.Body.String())
	}

	// Append one new matching record between page requests. It lands at seq
	// 231 because seq 230 already exists; its time is deliberately later
	// than every seed but still inside the window.
	added := mustPost(t, router, eventBody("alice", "2026-10-05T12:30:00Z"))
	if added["seq"] != float64(231) {
		t.Fatalf("interleaved append seq = %v, want 231", added["seq"])
	}

	// The already-full first segment is still byte-identical after the append.
	if again := comboFetchPage(t, router, firstQuery); again.Body.String() != firstBody {
		t.Fatalf("full segment changed after the interleaved append:\n%s\n%s", firstBody, again.Body.String())
	}

	// The last originally-matched alice is seq 229; seq 230 (alice at
	// 04:00:00Z)... allDay includes it: correct the expectation — allDay
	// matches 230 as well (account alice). Walk the tail from cursor 229.
	tail := comboFetchPage(t, router, comboBuildQuery("alice", allDay, 50, 229))
	tailEvents, tailNext := decodePage(t, tail)
	comboAssertSeqSet(t, "tail after append", tailEvents, []int64{230, 231})
	if tailNext != nil {
		t.Fatalf("tail next_after_seq = %v, want null", tailNext)
	}
	comboAssertRecordFields(t, tailEvents[1], added)

	// From the cursor of the first segment, all six original tail matches
	// plus the new record are visible on later pages.
	second := comboFetchPage(t, router,
		comboBuildQuery("alice", allDay, 100, int64(firstNext.(float64))))
	secondEvents, secondNext := decodePage(t, second)
	comboAssertSeqSet(t, "second segment", secondEvents, []int64{202, 204, 205, 209, 212, 231})
	if secondNext != nil {
		t.Fatalf("second segment next_after_seq = %v, want null", secondNext)
	}
}

// TestGetEventsCombinedVerifyAndTailContinuation verifies the chain after
// extensive combined paging: checked equals the number of successful
// appends, the ledger is valid, and further appends continue from the tail.
func TestGetEventsCombinedVerifyAndTailContinuation(t *testing.T) {
	router := NewRouter(openTestStore(t))
	posted := seedComboLedger(t, router)
	allDay := comboWindow{from: "2026-10-05T00:00:00Z", to: "2026-10-06T00:00:00Z"}

	// Exercise every page size against the ledger before verifying.
	for _, limit := range []int{1, 50, 100} {
		comboRunPageCase(t, router, posted, comboPageCase{
			name:     fmt.Sprintf("verify prelude limit %d", limit),
			account:  "alice",
			window:   allDay,
			limit:    limit,
			wantSeqs: comboAliceSeqsInWindow(allDay),
		})
	}

	assertComboVerify := func(wantChecked int64) {
		t.Helper()
		recorder := getLedgerVerifyRequest(t, router, "/ledger/verify")
		if recorder.Code != http.StatusOK {
			t.Fatalf("verify: status = %d (%s)", recorder.Code, recorder.Body.String())
		}
		body := decodeVerify(t, recorder)
		if !body.Valid || body.Checked != wantChecked || body.FirstInvalidSeq != nil {
			t.Fatalf("verify = %+v, want valid/%d/null", body, wantChecked)
		}
	}
	assertComboVerify(230)

	// A successful append after verification chains onto the old tail.
	after := mustPost(t, router, eventBody("alice", "2026-10-05T18:00:00Z"))
	if after["seq"] != float64(231) {
		t.Fatalf("append after verify: seq = %v, want 231", after["seq"])
	}
	if after["prev_hash"] != posted[229]["hash"] {
		t.Fatalf("append after verify: prev_hash = %v, want seq 230 hash %v", after["prev_hash"], posted[229]["hash"])
	}
	assertComboVerify(231)

	// One more append continues from the new tail.
	again := mustPost(t, router, eventBody("bob", "2026-10-05T19:00:00Z"))
	if again["seq"] != float64(232) || again["prev_hash"] != after["hash"] {
		t.Fatalf("second append = seq %v prev %v, want 232 chained to %v", again["seq"], again["prev_hash"], after["hash"])
	}
	assertComboVerify(232)
}

// assertComboErrorBody checks the published error envelope: exactly one
// top-level error object with string code and message, no partial page and
// no SQL, stack trace or path leakage.
func assertComboErrorBody(t *testing.T, recorder *httptest.ResponseRecorder, status int, code string) {
	t.Helper()
	if recorder.Code != status {
		t.Fatalf("status = %d, want %d (%s)", recorder.Code, status, recorder.Body.String())
	}
	var top map[string]json.RawMessage
	if err := json.Unmarshal(recorder.Body.Bytes(), &top); err != nil {
		t.Fatalf("decode error body: %v (%s)", err, recorder.Body.String())
	}
	if len(top) != 1 {
		t.Fatalf("top-level keys = %v, want only error", top)
	}
	var decoded struct {
		Error struct {
			Code    string `json:"code"`
			Message string `json:"message"`
		} `json:"error"`
	}
	if err := json.Unmarshal(recorder.Body.Bytes(), &decoded); err != nil {
		t.Fatalf("decode error body: %v", err)
	}
	if decoded.Error.Code != code {
		t.Fatalf("code = %q, want %q", decoded.Error.Code, code)
	}
	if decoded.Error.Message == "" {
		t.Fatal("message must be a non-empty string")
	}
	body := recorder.Body.String()
	for _, leak := range []string{"events", "next_after_seq", "SELECT", "INSERT", "sql", "SQL", "goroutine", ".go", "/", "\\"} {
		if strings.Contains(body, leak) {
			t.Fatalf("error body leaks %q or partial page data: %s", leak, body)
		}
	}
}

// TestGetEventsCombinedQueryErrors covers repeated parameters, illegal
// windows and out-of-range pagination values, all with the 400 envelope.
func TestGetEventsCombinedQueryErrors(t *testing.T) {
	router := NewRouter(openTestStore(t))
	seedComboLedger(t, router)
	cases := map[string]string{
		"repeated limit":           "limit=1&limit=2",
		"repeated account same":    "account=alice&account=alice",
		"repeated account differs": "account=alice&account=bob",
		"repeated from":            "from=2026-10-05T00:00:00Z&from=2026-10-05T00:00:00Z",
		"repeated after_seq":       "after_seq=1&after_seq=2",
		"unknown parameter":        "account=alice&cursor=1",
		"empty account":            "account=",
		"whitespace account":       "account=%20%09",
		"malformed time":           "from=not-a-time",
		"time without zone":        "to=2026-10-05T00:00:00",
		"leap second":              "from=2016-12-31T23:59:60Z",
		"from after to":            "from=2026-10-05T04:00:00Z&to=2026-10-05T03:00:00Z",
		"from equals to":           "from=2026-10-05T03:00:00Z&to=2026-10-05T03:00:00Z",
		"equal instant fractions":  "from=2026-10-05T03:00:00.5Z&to=2026-10-05T03:00:00.50Z",
		"equal instant offsets":    "from=2026-10-05T11:00:00%2B08:00&to=2026-10-05T03:00:00Z",
		"limit zero":               "limit=0",
		"limit over max":           "limit=101",
		"limit negative":           "limit=-1",
		"limit fraction":           "limit=1.5",
		"limit too large":          "limit=99999999999999999999",
		"after_seq negative":       "after_seq=-1",
		"after_seq overflow":       "after_seq=9223372036854775808",
		"bad percent escape":       "account=%zz",
	}
	for name, query := range cases {
		t.Run(name, func(t *testing.T) {
			assertComboErrorBody(t, getEventsQuery(t, router, query), http.StatusBadRequest, "invalid_audit_input")
		})
	}
}

// TestGetEventsCombinedStorageUnavailableAndPrecedence closes the store and
// proves parameter errors still return 400 while legal requests return 503
// storage_unavailable with the same bare error envelope.
func TestGetEventsCombinedStorageUnavailableAndPrecedence(t *testing.T) {
	st := openTestStore(t)
	router := NewRouter(st)
	mustPost(t, router, eventBody("alice", "2026-10-05T00:00:00Z"))
	st.Close()

	for _, query := range []string{
		"limit=0",
		"limit=1&limit=2",
		"from=2026-10-05T04:00:00Z&to=2026-10-05T03:00:00Z",
		"from=2026-10-05T03:00:00Z&to=2026-10-05T03:00:00Z",
		"after_seq=-1",
		"account=",
	} {
		assertComboErrorBody(t, getEventsQuery(t, router, query), http.StatusBadRequest, "invalid_audit_input")
	}

	for _, query := range []string{
		"",
		"account=alice",
		"account=alice&from=2026-10-05T00:00:00Z&to=2026-10-06T00:00:00Z&limit=1&after_seq=0",
		"limit=100",
	} {
		assertComboErrorBody(t, getEventsQuery(t, router, query), http.StatusServiceUnavailable, "storage_unavailable")
	}
}

